﻿#include "pch.h"
#include <tchar.h>
#include <windows.h>
#include <iostream>
#include <time.h>
#include <sys/timeb.h>
#include <math.h>
#define KEY_DOWN(VK_NONAME) ((GetAsyncKeyState(VK_NONAME) & 0x8000) ? 1:0)
using namespace std;
typedef struct MY_PARAMETER {
	DWORD line, y, x, dx, dy, type; //速度均*10000
}parameter, *parameterp;
typedef struct MY_PARAMETER_NULL {
	DWORD nul; //速度均*10000
}parameter_null, *parameterp_null;
union float2dword {
	float f;
	DWORD d;
}f2d;
DWORD __stdcall createBullet(LPVOID lParam)
{
	DWORD callAddr = 0x40D620;
	DWORD f600 = 0x44160000; //600的浮点数表示
	DWORD wan = 0x461C4000; //10000的浮点数表示
	parameter *lp;
	lp = (parameter*)lParam;
	DWORD line = lp->line;
	DWORD y = lp->y;
	DWORD x = lp->x;
	DWORD Dxx = lp->dx;
	DWORD Dy = lp->dy;
	DWORD TType = lp->type;
	__asm
	{
		pushad
		push TType
		push line
		push 0
		push y
		push x
		mov eax, 0x6A9EC0
		mov eax, [eax]
		mov eax, [eax + 0x768]
		call callAddr
		fld[eax + 0x4C]
		fadd f600
		fstp[eax + 0x4C] //将影子位置改成实际位置+600
		mov[eax + 0x58], 7
		mov[eax + 0x74], 1
		fld Dxx
		fstp[eax + 0x3C]
		fld Dy
		fstp[eax + 0x40]
		popad
	}
	return 0;
}
//创建初始的植物和僵尸
DWORD __stdcall createPlantAndZombie(LPVOID lParam)
{
	DWORD setPlant = 0x40D120;
	DWORD setZombie = 0x42A0F0;
	__asm
	{
		push -1
		push 1
		mov eax, 2
		push 8
		mov ebx, 0x6A9EC0
		mov ebx, [ebx]
		mov ebx, [ebx + 0x768]
		push ebx
		call setPlant
		mov ecx, 0x6A9EC0
		mov ecx, [ecx]
		mov ecx, [ecx + 0x768]
		mov ecx, [ecx + 0x160]
		mov eax, 2
		push 0
		push 24
		call setZombie
	}
}
long long getTimeStamp()
{
	timeb t;
	ftime(&t);
	return t.time * 1000 + t.millitm;
}
int main()
{
	int myId, bossId;
	HWND hWnd = FindWindow(NULL, _T("植物大战僵尸中文版"));
	DWORD pid;
	GetWindowThreadProcessId(hWnd, &pid);
	HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
	//创建初始植物和僵尸
	PVOID pRemoteThread = VirtualAllocEx(hProcess, NULL, 0x1000, MEM_COMMIT, PAGE_EXECUTE_READWRITE);
	WriteProcessMemory(hProcess, pRemoteThread, &createPlantAndZombie, 0x1000, 0);
	cout << pRemoteThread << endl;
	parameterp_null remoteParap_null = (parameterp_null)VirtualAllocEx(hProcess, NULL, sizeof(parameter_null), MEM_COMMIT, PAGE_READWRITE);
	parameter_null remotePara_null;
	DWORD dwThreadId = 0;
	HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteThread, remoteParap_null, 0, &dwThreadId);
	WaitForSingleObject(hThread, INFINITE);
	CloseHandle(hThread);
	//隐藏卡槽铲子
	DWORD base_addr = 0x006A9EC0;
	DWORD offset = 0x768;
	DWORD addr;
	ReadProcessMemory(hProcess, (LPVOID)base_addr, &addr, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + offset), &addr, 4, 0); //addr is [[6A9EC0]+768]
	DWORD deckAddr;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x144), &deckAddr, 4, 0);
	DWORD zero = 0;	
	WriteProcessMemory(hProcess, (LPVOID)(deckAddr + 0x18), &zero, 8, 0);
	WriteProcessMemory(hProcess, (LPVOID)(addr + 0x55F1), &zero, 3, 0);
	//放推车
	char zeroc = 0;
	DWORD carAddr, carNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x100), &carAddr, 4, 0);
	for (int i = 0; i < 5; i++)
	{
		WriteProcessMemory(hProcess, (LPVOID)(carAddr + 0x31 + 0x48 * i), &zero, 1, 0);
	}
	//Menu
	DWORD thousand = 1000;
	DWORD menuAddr;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x148), &menuAddr, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(menuAddr + 0x8), &thousand, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(menuAddr + 0xC), &thousand, 4, 0);
	//Debug
	//DWORD four = 4;
	//WriteProcessMemory(hProcess, (LPVOID)(addr + 0x55F8), &four, 4, 0);
	//获取自机和boss的ID
	DWORD plantsNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xB0), &plantsNumber, 4, 0);
	DWORD plantsStart;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xAC), &plantsStart, 4, 0);
	for (int i = 0; i < plantsNumber; i++)
	{
		DWORD plantClass, plantStatus;
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x24 + 0x14C * i), &plantClass, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x148 + 0x14C * i), &plantStatus, 4, 0);
		if (plantClass == 1 && (plantStatus & 0xFFFF0000) != 0)
		{
			bossId = i;
			break;
		}
	}
	DWORD zombiesNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x94), &zombiesNumber, 4, 0);
	DWORD zombiesStart;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x90), &zombiesStart, 4, 0);
	for (int i = 0; i < zombiesNumber; i++)
	{
		DWORD zombieClass;
		ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x24 + 0x15C * i), &zombieClass, 4, 0);
		if (zombieClass == 24)
		{
			myId = i;
			break;
		}
	}
	//修改判定
	DWORD ten = 10;
	DWORD forty = 50;
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x94 + 0x15C * myId), &ten, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x98 + 0x15C * myId), &ten, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x8C + 0x15C * myId), &forty, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x90 + 0x15C * myId), &forty, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xA4 + 0x15C * myId), &ten, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xA8 + 0x15C * myId), &ten, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x9C + 0x15C * myId), &forty, 4, 0);
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xA0 + 0x15C * myId), &forty, 4, 0);
	//向日葵不吐阳光
	DWORD sunCd = 999999;
	WriteProcessMemory(hProcess, (LPVOID)(plantsStart + 0x58 + 0x14C * bossId), &sunCd, 4, 0);
	DWORD bossHp = 450000;
	WriteProcessMemory(hProcess, (LPVOID)(plantsStart + 0x40 + 0x14C * bossId), &bossHp, 4, 0);
	//【test】无敌
	WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xC8 + 0x15C * myId), &bossHp, 4, 0);
	//获取自机基础位置
	DWORD myX, myY;
	ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x2C + 0x15C * myId), &myX, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x30 + 0x15C * myId), &myY, 4, 0);
	//写入发射子弹代码
	pRemoteThread = VirtualAllocEx(hProcess, NULL, 0x1000, MEM_COMMIT, PAGE_EXECUTE_READWRITE);
	WriteProcessMemory(hProcess, pRemoteThread, &createBullet, 0x1000, 0);
	cout << pRemoteThread << endl;
	//申请参数内存
	parameterp remoteParap = (parameterp)VirtualAllocEx(hProcess, NULL, sizeof(parameter), MEM_COMMIT, PAGE_READWRITE);
	parameter remotePara;
	//主进程
	while (1)
	{
		//隐藏coinbank
		WriteProcessMemory(hProcess, (LPVOID)(addr + 0x55F4), &zero, 4, 0);
		//根据boss血量显示进度
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x40 + 0x14C * bossId), &bossHp, 4, 0);
		DWORD tab = (bossHp - 300000) / 1000;
		if (tab > 150) tab = 0;
		WriteProcessMemory(hProcess, (LPVOID)(addr + 0x5610), &tab, 4, 0);
		//自机移动
		float dx = 0.0;
		float dy = 0.0;
		if (KEY_DOWN(37)) dx = -3.0;
		if (KEY_DOWN(38)) dy = -3.0;
		if (KEY_DOWN(39)) dx = 3.0;
		if (KEY_DOWN(40)) dy = 3.0;
		if (KEY_DOWN(VK_SHIFT))
		{
			dx /= 2;
			dy /= 2;
		}
		f2d.d = myX;
		f2d.f += dx;
		myX = f2d.d;
		WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x2C + 0x15C * myId), &myX, 4, 0);
		f2d.d = myY;
		f2d.f += dy;
		myY = f2d.d;
		WriteProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x30 + 0x15C * myId), &myY, 4, 0);
		//自机射击
		if (KEY_DOWN('Z'))
		{
			int bossX, bossY, myPicX, myPicY;
			ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x8 + 0x15C * myId), &myPicX, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xC + 0x15C * myId), &myPicY, 4, 0);
			float r = atan(((float)bossY - (float)myPicY) / ((float)bossX - (float)myPicX));
			float flag;
			if (myPicX > bossX) flag = -1;
			else flag = 1;
			float dx = 20.0 * cos(r) * flag;
			float dy = 20.0 * sin(r) * flag;
			//写入参数
			remotePara.x = myPicX + 40;
			remotePara.y = myPicY + 40;
			remotePara.line = 5;
			f2d.f = dx;
			remotePara.dx = f2d.d;
			f2d.f = dy;
			remotePara.dy = f2d.d;
			remotePara.type = 13; //13僵尸子弹
			WriteProcessMemory(hProcess, remoteParap, &remotePara, sizeof(parameter), 0);
			//创建远程线程
			DWORD dwThreadId = 0;
			HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteThread, remoteParap, 0, &dwThreadId);
			WaitForSingleObject(hThread, INFINITE);
			CloseHandle(hThread);
			//固定弹
			//写入参数
			remotePara.x = myPicX + 40;
			remotePara.y = myPicY + 50;
			remotePara.line = 5;
			f2d.f = 20.0;
			remotePara.dx = f2d.d;
			f2d.f = 0.001;
			remotePara.dy = f2d.d;
			remotePara.type = 13; //13僵尸子弹
			WriteProcessMemory(hProcess, remoteParap, &remotePara, sizeof(parameter), 0);
			//创建远程线程
			dwThreadId = 0;
			hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteThread, remoteParap, 0, &dwThreadId);
			WaitForSingleObject(hThread, INFINITE);
			CloseHandle(hThread);
			//写入参数
			remotePara.x = myPicX + 40;
			remotePara.y = myPicY + 30;
			remotePara.line = 5;
			f2d.f = 20.0;
			remotePara.dx = f2d.d;
			f2d.f = -0.001;
			remotePara.dy = f2d.d;
			remotePara.type = 13; //13僵尸子弹
			WriteProcessMemory(hProcess, remoteParap, &remotePara, sizeof(parameter), 0);
			//创建远程线程
			dwThreadId = 0;
			hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteThread, remoteParap, 0, &dwThreadId);
			WaitForSingleObject(hThread, INFINITE);
			CloseHandle(hThread);
		}
		Sleep(10);
	}
	return 0;
}

