﻿#include "pch.h"
#include <tchar.h>
#include <windows.h>
#include <iostream>
#include <time.h>
#include <sys/timeb.h>
#include <math.h>
#include <thread>
#define KEY_DOWN(VK_NONAME) ((GetAsyncKeyState(VK_NONAME) & 0x8000) ? 1:0)
using namespace std;

int myId, bossId;
HWND hWnd;
DWORD pid;
HANDLE hProcess;
DWORD base_addr = 0x006A9EC0;
DWORD offset = 0x768;
DWORD addr;
PVOID pRemoteThread;
DWORD zombiesStart;
DWORD plantsStart;

typedef struct MY_PARAMETER {
	DWORD line, y, x, dx, dy, type, hit; //速度均*10000
}parameter, *parameterp;
parameterp remoteParap;
parameter remotePara;
union float2dword {
	float f;
	DWORD d;
}f2d;

DWORD __stdcall createBullet(LPVOID lParam)
{
	DWORD callAddr = 0x40D620;
	DWORD f600 = 0x44160000; //600的浮点数表示
	DWORD wan = 0x461C4000; //10000的浮点数表示
	parameter *lp;
	lp = (parameter*)lParam;
	DWORD line = lp->line;
	DWORD y = lp->y;
	DWORD x = lp->x;
	DWORD Dxx = lp->dx;
	DWORD Dy = lp->dy;
	DWORD TType = lp->type;
	DWORD hit = lp->hit;
	__asm
	{
		pushad
		push TType
		push line
		push 1000
		push y
		push x
		mov eax, 0x6A9EC0
		mov eax, [eax]
		mov eax, [eax + 0x768]
		call callAddr
		mov[eax + 0x58], 7
		mov edx, hit
		mov[eax + 0x74], edx
		fld Dxx
		fstp[eax + 0x3C]
		fld Dy
		fstp[eax + 0x40]
		popad
	}
	return 0;
}
int randStar()
{
	int type = rand() % 4;
	if (type == 0) return 4;
	else if (type == 1) return 2;
	else if (type == 2) return 8;
	else if (type == 3) return 10;
}
int randBigStar()
{
	int type = rand() % 3;
	if (type == 0) return 3;
	else if (type == 1) return 5;
	else if (type == 2) return 9;
}
long long getTimeStamp()
{
	timeb t;
	ftime(&t);
	return t.time * 1000 + t.millitm;
}
void getId()
{
	DWORD plantsNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xB0), &plantsNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xAC), &plantsStart, 4, 0);
	for (int i = 0; i < plantsNumber; i++)
	{
		DWORD plantClass, plantStatus;
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x24 + 0x14C * i), &plantClass, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x148 + 0x14C * i), &plantStatus, 4, 0);
		if (plantClass == 1 && (plantStatus & 0xFFFF0000) != 0)
		{
			bossId = i;
			break;
		}
	}
	DWORD zombiesNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x94), &zombiesNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x90), &zombiesStart, 4, 0);
	for (int i = 0; i < zombiesNumber; i++)
	{
		DWORD zombieClass;
		ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x24 + 0x15C * i), &zombieClass, 4, 0);
		if (zombieClass == 24)
		{
			myId = i;
			break;
		}
	}
	return;
}
void shot(DWORD line, int x, int y, float dx, float dy, DWORD type, DWORD hit)
{
	remotePara.x = x;
	remotePara.y = y;
	remotePara.line = 7;
	remotePara.type = type;
	f2d.f = dx;
	remotePara.dx = f2d.d;
	f2d.f = dy;
	remotePara.dy = f2d.d;
	remotePara.hit = hit;
	WriteProcessMemory(hProcess, remoteParap, &remotePara, sizeof(parameter), 0);
	//创建远程线程
	DWORD dwThreadId = 0;
	HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)pRemoteThread, remoteParap, 0, &dwThreadId);
	WaitForSingleObject(hThread, INFINITE);
	CloseHandle(hThread);
	return;
}
void laser(int x, int y, float r, float d, int t)
{
	while (t -= 20)
	{
		shot(5, x, y, 10 * cos(r), 10 * sin(r), 1, 0);
		r += d;
		Sleep(20);
	}
	return;
}
void bossMove(int dx, int dy, DWORD time)
{
	int bossX, bossY;
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
	while (time-=10)
	{
		bossX += dx; bossY += dy;
		WriteProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
		WriteProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
		Sleep(10);
	}
}
double randAngle(int a, int b)
{
	int degree = (rand() % (b - a + 1)) + a;
	cout << degree << endl;
	return degree * 0.01744444;
}
void clear()
{
	DWORD bulletNumber, bulletStart;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xCC), &bulletNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xC8), &bulletStart, 4, 0);
	for (int i = 0; i < bulletNumber; i++)
	{
		DWORD bulletType, bulletX, bulletY;
		ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x5C + 0x94 * i), &bulletType, 4, 0);
		if (bulletType == 13)continue;
		f2d.f = 1000.0;
		WriteProcessMemory(hProcess, (LPVOID)(bulletStart + 0x30 + 0x94 * i), &f2d.d, 4, 0);
	}
}
void milkyWay()
{
	DWORD tab;
	int bossX, bossY;
	float r = 0;
	while (1)
	{
		ReadProcessMemory(hProcess, (LPVOID)(addr + 0x5610), &tab, 4, 0);
		if (tab == 0)
		{
			return;
		}
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
		for (int i = 0; i < 4; i++)
		{
			shot(5, bossX, bossY, 3.33*cos(r + 1.57 * i), 3.33*sin(r + 1.57 * i), randBigStar(), 0);
		}
		double angle = randAngle(45, 135);
		shot(5, rand() % 801, -100, 1*cos(angle), 1*sin(angle), randStar(), 0);
		angle = randAngle(225, 315);
		shot(5, rand() % 801, 700, 1*cos(angle), 1*sin(angle), randStar(), 0);
		r += 0.17444;
		Sleep(500);
	}
}
void starDust_move()
{
	DWORD tab;
	DWORD bulletNumber, bulletStart;
	int bossX, bossY;
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
	while (1)
	{
		ReadProcessMemory(hProcess, (LPVOID)(addr + 0x5610), &tab, 4, 0);
		if (tab == 0)return;
		ReadProcessMemory(hProcess, (LPVOID)(addr + 0xCC), &bulletNumber, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(addr + 0xC8), &bulletStart, 4, 0);
		for (int i = 0; i < bulletNumber; i++)
		{
			DWORD bulletType, bulletTime;
			int bulletX, bulletY;
			float dx, dy;
			ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x5C + 0x94 * i), &bulletType, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x60 + 0x94 * i), &bulletTime, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x3C + 0x94 * i), &dx, 4, 0);
			ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x40 + 0x94 * i), &dy, 4, 0);
			if (bulletType != 13 && bulletTime >= 500 && dx == 0.0 && dy == 0.0)
			{
				ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x8 + 0x94 * i), &bulletX, 4, 0);
				ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0xC + 0x94 * i), &bulletY, 4, 0);
				float r = atan(((float)bossY - (float)bulletY) / ((float)bossX - (float)bulletX)) + 0.314;
				float flag;
				if (bulletX > bossX) flag = -1;
				else flag = 1;
				if (bulletType == 10 || bulletType == 4) flag *= -1;
				float dx = 1 * cos(r) * flag;
				float dy = 1 * sin(r) * flag;
				WriteProcessMemory(hProcess, (LPVOID)(bulletStart + 0x3C + 0x94 * i), &dx, 4, 0);
