union float2dword {
	float f;
	DWORD d;
}f2d;
long long getTimeStamp()
{
	timeb t;
	ftime(&t);
	return t.time * 1000 + t.millitm;
}
void getId()
{
	DWORD plantsNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xB0), &plantsNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xAC), &plantsStart, 4, 0);
	for (int i = 0; i < plantsNumber; i++)
	{
		DWORD plantClass, plantStatus;
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x24 + 0x14C * i), &plantClass, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x148 + 0x14C * i), &plantStatus, 4, 0);
		if (plantClass == 1 && (plantStatus & 0xFFFF0000) != 0)
		{
			bossId = i;
			break;
		}
	}
	DWORD zombiesNumber;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x94), &zombiesNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0x90), &zombiesStart, 4, 0);
	for (int i = 0; i < zombiesNumber; i++)
	{
		DWORD zombieClass;
		ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x24 + 0x15C * i), &zombieClass, 4, 0);
		if (zombieClass == 24)
		{
			myId = i;
			break;
		}
	}
	return;
}
void clear()
{
	DWORD bulletNumber, bulletStart;
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xCC), &bulletNumber, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(addr + 0xC8), &bulletStart, 4, 0);
	for (int i = 0; i < bulletNumber; i++)
	{
		DWORD bulletType, bulletX, bulletY;
		ReadProcessMemory(hProcess, (LPVOID)(bulletStart + 0x5C + 0x94 * i), &bulletType, 4, 0);
		if (bulletType == 13)continue;
		f2d.f = 1000.0;
		WriteProcessMemory(hProcess, (LPVOID)(bulletStart + 0x30 + 0x94 * i), &f2d.d, 4, 0);
	}
}
